                        count_non_bg += 1
            if count_non_bg == len(neighbor_colors) and count_non_bg > 0:
                grid_list[r][c] = list(neighbor_colors)[0]
            else:
                # Copy original non-bg value
                if val != bg:
                    grid_list[r][c] = val
    return grid_list

