]

rows, cols = len(input_grid), len(input_grid[0])
background = 8

# Let me check what happens if I just remove isolated bg pixels completely enclosed
# by same-color neighbors (including diagonals)

def classify_enclosed(bg_cell):
    r, c = bg_cell
    # Check if THIS cell is completely surrounded by ONE color
    ortho_neighbors = set()
    diag_neighbors = set()

    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            val = input_grid[nr][nc]
            if val != background:
                ortho_neighbors.add(val)
            elif not ((dr == 0 and (dc == -1 or dc == 1)) or (dc == 0 and (dr == -1 or dr == 1))):
                pass  # diagonal is different handling
            else:
                diag_neighbors.add(val)

    for dr in [-1, 1]:
        for dc in [-1, 1]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                val = input_grid[nr][nc]
                if val != background:
                    diag_neighbors.add(val)

    return len(ortho_neighbors), len(diag_neighbors)

# Find holes and see which ones should be filled
holes = []
for r in range(rows):
    for c in range(cols):
        if input_grid[r][c] == background:
            oh, dh = classify_enclosed((r,c))
            holes.append(((r,c), oh, dh))

print("Holes with (ortho_colors, diag_colors) neighbors:")
for h, oh, dh in sorted(holes)[:20]:
    print(f"{h}: oh={oh}, dh={dh}")

# Now try a different approach: what if the rule is to FILL holes until NO holes remain?
# Using 4-way orthogonality only, iterate until fixed point

def remove_all_holes(grid):
    """Remove ALL holes - bg cells completely enclosed by single non-bg color"""
    output = [[val for val in row] for row in grid]

    changed = True
    while changed:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if output[r][c] == background:
                    # Check ortho-only neighbors
                    ortho_colors = set()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            nval = output[nr][nc]
                            if nval != background:
                                ortho_colors.add(nval)

                    if len(ortho_colors) == 1:
                        output[r][c] = list(ortho_colors)[0]
                        changed = True

    return output

output_no_holes = remove_all_holes(input_grid)
print("\nNo-holes result:")
for i, row in enumerate(output_no_holes[:8]):
    print(' '.join(str(c) for c in row))

# Check counts
counts2 = {}
for r in range(rows):
    for c in range(cols):
        v = output_no_holes[r][c]
        if v != background:
            counts2[v] = counts2.get(v, 0) + 1
print(f"\nCounts after no-hole removal: {sorted(counts2.items())}")

